    public virtual Dictionary<string, object> parseWsTicker(IDictionary<string, object> ticker, object market = null)
    {
        //
        //  public
        //    {
        //        "symbol1": "LRC",
        //        "symbol2": "USD",
        //        "price": "0.305",
        //        "open24": "0.301",
        //        "volume": "241421.641700"
        //    }
        //  private
        //    {
        //        "timestamp": "1663764969",
        //        "low": "18756.3",
        //        "high": "19200",
        //        "last": "19200",
        //        "volume": "0.94735907",
        //        "volume30d": "64.61299999",
        //        "bid": 19217.2,
        //        "ask": 19247.5,
        //        "priceChange": "44.3",
        //        "priceChangePercentage": "0.23",
        //        "pair": ["BTC", "USDT"]
        //    }
        List<object> pair = this.safeList(ticker, "pair", new List<object>() {});
        string? baseId = this.safeString(ticker, "symbol1");
        if ((baseId == null))
        {
            baseId = this.safeString(pair, 0);
        }
        string? quoteId = this.safeString(ticker, "symbol2");
        if ((quoteId == null))
        {
            quoteId = this.safeString(pair, 1);
        }
        string? bs = this.safeCurrencyCode(baseId);
        string? quote = this.safeCurrencyCode(quoteId);
        string? symbol = null;
        if (((bs != null)) && ((quote != null)))
        {
            symbol = ((bs + "/") + quote);
        }
        Int64? timestamp = this.safeInteger(ticker, "timestamp");
        if ((timestamp != null))
        {
            timestamp = (timestamp * 1000);
        }
        return this.safeTicker(new Dictionary<string, object>() {
            { "symbol", symbol },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "high", this.safeString(ticker, "high") },
            { "low", this.safeString(ticker, "low") },
            { "bid", this.safeString(ticker, "bid") },
            { "bidVolume", null },
            { "ask", this.safeString(ticker, "ask") },
            { "askVolume", null },
            { "vwap", null },
            { "open", this.safeString(ticker, "open24") },
            { "close", null },
            { "last", this.safeString2(ticker, "price", "last") },
            { "previousClose", null },
            { "change", this.safeString(ticker, "priceChange") },
            { "percentage", this.safeString(ticker, "priceChangePercentage") },
            { "average", null },
            { "baseVolume", null },
            { "quoteVolume", this.safeString(ticker, "volume") },
